t <- function(label, expr) { r <- tryCatch({ v <- expr; paste(capture.output(str(v, give.attr = FALSE)), collapse = " | ") }, error = function(e) paste0("ERROR<", class(e)[1], "> ", conditionMessage(e)), warning = function(w) paste0("WARNING<", class(w)[1], "> ", conditionMessage(w))); cat(sprintf("%-50s %s\n", label, substr(r, 1, 260))) }
cs <- function() unlist(zuregex:::cache_stats())
