base <- re_detect(x[c(1,2,3,5)], r)
t("base", base)
re_cache_clear(); invisible(gc()); t("after clear+gc", identical(re_detect(x[c(1,2,3,5)], r), base))
re_cache_size(0); invisible(gc()); t("after size 0+gc", identical(re_detect(x[c(1,2,3,5)], r), base)); re_cache_size(128)
tf <- tempfile(); saveRDS(r, tf); rr <- readRDS(tf)
